import './style.css'
import * as T from 'three'
import {spider,human,fly,web} from './models.js'
import {createWorld} from './world.js'
import {loadSpiderModel} from './spider-model.js'
import {GOAL,freshState,collect,hit,finish,blocked,stepSurface} from './rules.js'

const app=document.querySelector('#app')
app.innerHTML=`
<div id="viewport"></div><div class="vignette"></div>
<header><a class="brand" href="./"><span class="brand-icon">✳</span> ТИХИЙ СОСЕД <small>3D ПРИКЛЮЧЕНИЕ</small></a><div class="top-actions"><span class="live">● ЛЁГКИЙ РЕЖИМ</span><button id="sound" aria-label="Включить звук">Звук: выкл.</button><button id="controls-toggle" aria-label="Экранное управление" aria-pressed="false">⌨</button><button id="pause" aria-label="Пауза">Ⅱ</button></div></header>
<section id="hud"><div class="objective"><span class="eyebrow">ОПЕРАЦИЯ «СЫТЫЙ ПАУК»</span><h2 id="objective">Поймай 6 мух</h2><p id="hint">Потом возвращайся в светящееся убежище</p><div id="progress" aria-label="Пойманные мухи"></div></div><div class="vitals"><span class="eyebrow">ТВОЙ ЗАПАС УДАЧИ</span><div id="health"></div><span id="danger">Человек занят своими делами</span><div class="meter"><i id="fear"></i></div></div></section>
<div id="surface">ПОЛ <span>•</span> лапки держатся крепко</div><div id="toast" role="status"></div>
<div id="overlay"><div class="intro"><div class="tag">МАЛЕНЬКИЙ ГЕРОЙ. БОЛЬШОЙ ДОМ.</div><h1>Тихий<br><em>сосед.</em></h1><p id="description">Для человека ты — незваный гость.<br>Для тебя это просто дом с вкусными мухами.</p><div class="mission"><span>01 <b>Поймай 6 мух</b></span><span>02 <b>Обхитри человека</b></span><span>03 <b>Вернись домой</b></span></div><button id="start" class="primary">Начать приключение <span>↗</span></button><p class="note">5 жизней · без таймера · паутина спасает</p><span id="best"></span></div><div class="scene-label"><span>ДОМАШНЯЯ ЭКСПЕДИЦИЯ / 01</span><h3>Не всё большое<br>здесь страшное.</h3><p>Стены и потолок — твоя безопасная дорога.</p></div></div>
<footer><div class="controls"><span><kbd>W A S D</kbd> движение</span><span><kbd>← →</kbd> поворот</span><span><kbd>Пробел</kbd> прыжок</span><span><kbd>E</kbd> паутина</span><span><kbd>Esc</kbd> пауза</span></div><span class="footer-note">СДЕЛАНО ИЗ ПАУТИНЫ И СМЕЛОСТИ</span></footer>
<div class="touch"><button data-key="KeyW" aria-label="Вперёд">↑</button><div><button data-key="ArrowLeft" aria-label="Повернуть налево">↶</button><button data-key="KeyS" aria-label="Назад">↓</button><button data-key="ArrowRight" aria-label="Повернуть направо">↷</button></div><button id="web-button">Паутина E</button><button id="jump-button">Прыжок</button></div>`
const $=id=>document.getElementById(id)
let renderer
try{renderer=new T.WebGLRenderer({antialias:true,powerPreference:'high-performance'})}catch{ $('description').textContent='Для игры нужен браузер с WebGL 2. Включи аппаратное ускорение и перезагрузи страницу.'; $('start').disabled=true;throw new Error('WebGL 2 недоступен') }
renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.2
$('viewport').append(renderer.domElement);renderer.domElement.setAttribute('aria-label','Трёхмерная комната: паук против человека')
const scene=new T.Scene(),camera=new T.PerspectiveCamera(52,1,.08,90), world=createWorld(scene)
const player=spider(), person=human(); scene.add(player,person)
const modelStatus=document.createElement('span');modelStatus.id='model-status';modelStatus.setAttribute('role','status');modelStatus.textContent=' · Паук загружается…';document.querySelector('.note').append(modelStatus)
loadSpiderModel(player).then(({animation})=>{modelStatus.textContent=` · 3D-паук готов · Анимация включена`;modelStatus.title=animation}).catch(error=>{console.error('Не удалось загрузить GLB паука:',error);modelStatus.textContent=' · Резервный паук (модель не загрузилась)'})
const credit=document.createElement('a');credit.href=`${import.meta.env.BASE_URL}models/CREDITS.md`;credit.textContent='Паук: maksroberthut · CC BY 4.0';credit.target='_blank';credit.rel='noopener';document.querySelector('.footer-note').replaceWith(credit)
const normal=new T.Vector3(0,1,0),forward=new T.Vector3(0,0,-1),position=new T.Vector3(-7,0,5),up=new T.Vector3(0,1,0)
const flies=[],traps=[],keys=new Set(),nest=new T.Vector3(-7,0,5)
const flySpawns=[[-5,0,4],[-2,0,4],[2,0,5],[6,0,4],[8,0,-1],[5,0,-2],[-7,0,-2],[0,0,-5],[-10,2,1],[10,2,4],[0,6,1],[-5,6,-4]]
let state=freshState(),mode='menu',time=0,jump=0,jumpVelocity=0,attack=0,attackCooldown=0,muted=true,audio,toastTimer=0,patrol=0,walk=0,drag=null
const patrolPoints=[new T.Vector3(2,0,-1),new T.Vector3(6,0,4),new T.Vector3(-2,0,5),new T.Vector3(0,0,-5)]
function sound(freq=500){if(muted)return;try{audio??=new AudioContext();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(freq*.5,audio.currentTime+.15);g.gain.setValueAtTime(.045,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.18);o.start();o.stop(audio.currentTime+.2)}catch{}}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');toastTimer=3}
function reset(){
  player.userData.resetAnimation?.()
  state=freshState();position.copy(nest);normal.copy(up);forward.set(0,0,-1);person.position.set(3,0,-1);jump=0;jumpVelocity=0;attack=0;attackCooldown=2;patrol=0;keys.clear()
  for(const f of flies)scene.remove(f.mesh);flies.length=0
  for(const t of traps)scene.remove(t.mesh);traps.length=0
  flySpawns.forEach((p,i)=>{const mesh=fly(),base=new T.Vector3(...p),n=new T.Vector3(0,1,0);const halo=new T.Mesh(new T.TorusGeometry(.3,.015,5,24),new T.MeshBasicMaterial({color:'#ffd38b'}));halo.rotation.x=Math.PI/2;halo.position.y=-.13;mesh.add(halo);if(p[0]===-10)n.set(1,0,0);if(p[0]===10)n.set(-1,0,0);if(p[1]===6)n.set(0,-1,0);base.addScaledVector(n,.38);mesh.position.copy(base);scene.add(mesh);flies.push({mesh,base,phase:i*1.9,alive:true})})
  updateHUD()
}
function updateHUD(){
  $('health').textContent='♥ '.repeat(state.health)+'♡ '.repeat(5-state.health)
  $('health').setAttribute('aria-label',`Здоровье: ${state.health} из 5`)
  $('progress').innerHTML=Array.from({length:GOAL},(_,i)=>`<i class="${i<state.caught?'filled':''}">${i<state.caught?'✓':'•'}</i>`).join('')
  $('objective').textContent=state.caught>=GOAL?'Вернись в убежище!':`Поймай 6 мух · ${state.caught}/6`
  $('hint').textContent=state.caught>=GOAL?'Светящийся круг в углу комнаты ждёт тебя':'Подойди к мухе — паук поймает её сам'
}
function start(){reset();document.body.classList.remove('paused');mode='playing';$('overlay').classList.add('hidden');document.body.classList.add('playing');$('pause').textContent='Ⅱ';toast('Лови золотистые огоньки. Ты справишься!');sound(700)}
function pause(){if(mode==='menu'||mode==='won'||mode==='lost')return;mode=mode==='paused'?'playing':'paused';keys.clear();document.body.classList.toggle('paused',mode==='paused');$('overlay').classList.toggle('hidden',mode==='playing');$('start').innerHTML=mode==='paused'?'Продолжить ↗':'Начать приключение ↗';$('description').textContent='Игра на паузе. Человек тоже отдыхает.';$('pause').textContent=mode==='paused'?'▶':'Ⅱ'}
function end(){mode=state.status;$('overlay').classList.remove('hidden');document.body.classList.remove('playing');$('start').innerHTML='Ещё одно приключение ↗';$('description').textContent=mode==='won'?`Победа! Все 6 мух пойманы, а ты дома. Время: ${Math.floor(state.elapsed)} сек. Человек так ничего и не понял.`:'Тапок оказался быстрее. Попробуй стены, прыжки и паутину — у тебя получится!';if(mode==='won'){sound(1000);try{const old=Number(localStorage.getItem('quiet-neighbor-best'))||Infinity;localStorage.setItem('quiet-neighbor-best',Math.min(old,Math.floor(state.elapsed)))}catch{}}updateBest()}
function updateBest(){try{const b=localStorage.getItem('quiet-neighbor-best');$('best').textContent=b?`Лучшее приключение: ${b} сек.`:''}catch{}}
function weave(){if(mode!=='playing')return;if(state.cooldown>0){toast(`Паутина восстановится через ${Math.ceil(state.cooldown)} сек.`);return}const mesh=web(1.3);mesh.position.copy(position).addScaledVector(normal,.04);mesh.quaternion.setFromUnitVectors(up,normal);scene.add(mesh);traps.push({mesh,life:18});state.cooldown=4;toast('Ловушка готова! Заманивай человека.');sound(300)}
function leap(){if(mode==='playing'&&jump===0){jumpVelocity=4.7;sound(400)}}
$('start').onclick=()=>mode==='paused'?pause():start();$('pause').onclick=pause;$('web-button').onclick=weave;$('jump-button').onclick=leap
$('sound').onclick=()=>{muted=!muted;$('sound').textContent=muted?'Звук: выкл.':'Звук: вкл.';$('sound').setAttribute('aria-label',muted?'Включить звук':'Выключить звук');sound()}
window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Escape'].includes(e.code))e.preventDefault();if(!e.repeat){if(e.code==='Escape')pause();if(e.code==='KeyE')weave();if(e.code==='Space')leap()}keys.add(e.code)})
window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{keys.clear();if(mode==='playing')pause()})
document.addEventListener('visibilitychange',()=>{if(document.hidden&&mode==='playing')pause()})
$('controls-toggle').onclick=()=>{const visible=document.body.classList.toggle('show-controls');$('controls-toggle').setAttribute('aria-pressed',String(visible))}
for(const b of document.querySelectorAll('[data-key]')){let pressedAt=0,timer;b.onpointerdown=e=>{e.preventDefault();clearTimeout(timer);pressedAt=performance.now();b.setPointerCapture(e.pointerId);keys.add(b.dataset.key)};b.onpointerup=()=>{timer=setTimeout(()=>keys.delete(b.dataset.key),Math.max(0,250-(performance.now()-pressedAt)))};b.onpointercancel=()=>{clearTimeout(timer);keys.delete(b.dataset.key)}}
renderer.domElement.onpointerdown=e=>{drag=e.clientX;renderer.domElement.setPointerCapture(e.pointerId)}
renderer.domElement.onpointermove=e=>{if(drag!==null&&mode==='playing'){forward.applyAxisAngle(normal,-(e.clientX-drag)*.006);drag=e.clientX}}
renderer.domElement.onpointerup=renderer.domElement.onpointercancel=()=>drag=null
function move(dt){
  const turn=(keys.has('ArrowLeft')?1:0)-(keys.has('ArrowRight')?1:0);forward.applyAxisAngle(normal,turn*2.1*dt)
  const right=new T.Vector3().crossVectors(forward,normal),movement=new T.Vector3()
  const f=(keys.has('KeyW')||keys.has('ArrowUp')?1:0)-(keys.has('KeyS')||keys.has('ArrowDown')?1:0),r=(keys.has('KeyD')?1:0)-(keys.has('KeyA')?1:0)
  movement.addScaledVector(forward,f).addScaledVector(right,r);const moving=movement.lengthSq()>0
  const before=position.clone(),oldNormal=normal.clone(),oldForward=forward.clone()
  if(moving){movement.normalize().multiplyScalar(3.5*dt);stepSurface(position,normal,forward,movement,T.Quaternion,T.Vector3);if(normal.y>.5&&jump<.65&&blocked(position.x,position.z,world.obstacles)){position.copy(before);normal.copy(oldNormal);forward.copy(oldForward)}}
  jumpVelocity-=10*dt;jump=Math.max(0,jump+jumpVelocity*dt);if(jump===0)jumpVelocity=0
  player.position.copy(position).addScaledVector(normal,jump+.04)
  const basis=new T.Matrix4().makeBasis(new T.Vector3().crossVectors(forward,normal),normal,forward.clone().negate());player.quaternion.slerp(new T.Quaternion().setFromRotationMatrix(basis),Math.min(1,dt*14))
  walk+=moving?dt*17:dt
  player.userData.moving=moving&&position.distanceToSquared(before)>0.000001
  if(!player.userData.updateAnimation)player.userData.legs.forEach((leg,i)=>{leg.rotation.y=moving?Math.sin(walk+i*Math.PI*.75)*.25:Math.sin(walk*2+i)*.025})
  player.visible=state.invincible<=0||Math.floor(time*12)%2===0
  $('surface').innerHTML=(normal.y>.5?'ПОЛ':normal.y<-.5?'ПОТОЛОК':'СТЕНА')+' <span>•</span> '+(state.cooldown>0?`паутина: ${Math.ceil(state.cooldown)} с`:'паутина готова')
}
function ai(dt){
  const delta=position.clone().sub(person.position),distance=delta.length(),safe=position.distanceTo(nest)<1.8
  const chase=position.y<1.5&&distance<6&&!safe;state.stun=Math.max(0,state.stun-dt);attackCooldown=Math.max(0,attackCooldown-dt)
  $('danger').textContent=state.stun>0?'Человек запутался в паутине!':attack>0?'Прыгай! Сейчас будет удар!':chase?'Тебя заметили! Беги или плети паутину':'Человек занят своими делами'
  $('fear').style.width=(chase?Math.max(10,100-distance*12):state.stun>0?0:8)+'%'
  if(state.stun<=0&&attack===0){const target=chase?position:patrolPoints[patrol],dir=target.clone().sub(person.position);dir.y=0;if(dir.length()<.4){if(!chase)patrol=(patrol+1)%patrolPoints.length}else{
    dir.normalize();const next=person.position.clone().addScaledVector(dir,dt*(chase?1.65:.8));if(!blocked(next.x,next.z,world.obstacles))person.position.copy(next);else if(!chase)patrol=(patrol+1)%patrolPoints.length
    person.rotation.y=Math.atan2(-dir.x,-dir.z);person.userData.legs.forEach((leg,i)=>leg.rotation.x=Math.sin(time*5+i*Math.PI)*.3)
  }if(chase&&distance<1.35&&attackCooldown===0){attack=.85;attackCooldown=2.6;sound(160)}}
  if(attack>0){attack-=dt;person.userData.slipper.rotation.x=-Math.sin(Math.max(0,attack)/.85*Math.PI)*2;if(attack<=0&&distance<1.55&&jump<.55&&!safe&&state.stun===0){if(hit(state)){sound(110);toast('Ой! Осторожнее с тапком. Есть ещё шансы.');updateHUD()}}}
  for(let i=traps.length-1;i>=0;i--){const t=traps[i];t.life-=dt;if(t.life<=0){scene.remove(t.mesh);traps.splice(i,1)}else if(t.mesh.position.y<.2&&t.mesh.position.distanceTo(person.position)<1.4){state.stun=5;attack=0;person.userData.slipper.rotation.x=0;scene.remove(t.mesh);traps.splice(i,1);toast('Попался! Человек задержан на 5 секунд.');sound(250)}}
}
function animate(dt){
  time+=dt;toastTimer-=dt;if(toastTimer<=0)$('toast').classList.remove('show')
  if(mode==='playing'){
    state.elapsed+=dt;state.invincible=Math.max(0,state.invincible-dt);state.cooldown=Math.max(0,state.cooldown-dt);move(dt);ai(dt)
    for(const f of flies){if(!f.alive)continue;f.mesh.position.copy(f.base);f.mesh.position.y+=Math.sin(time*3+f.phase)*.12;f.mesh.rotation.y=time+f.phase;f.mesh.children.slice(1,3).forEach((w,i)=>w.rotation.z=Math.sin(time*45)*.45*(i?1:-1));if(f.mesh.position.distanceTo(player.position)<.9){f.alive=false;scene.remove(f.mesh);collect(state);updateHUD();sound(650+state.caught*60);toast(state.caught===GOAL?'Все мухи пойманы! Возвращайся к светящемуся кругу.':`Вкусно! Поймано ${state.caught} из ${GOAL}`)}}
    finish(state,position.distanceTo(nest));if(state.status!=='playing')end()
  }
  player.userData.updateAnimation?.(dt,mode==='playing'&&player.userData.moving,mode!=='playing'&&mode!=='menu')
  world.ring.scale.setScalar(1+Math.sin(time*2)*.04)
  if(mode==='menu'){player.position.copy(nest);person.position.set(3,0,-1);camera.position.set(-.5,5.7,12.5);camera.lookAt(-2,1,0)}else{
    const target=player.position.clone().addScaledVector(normal,.45), desired=target.clone().addScaledVector(forward,-4.4).addScaledVector(normal,2.7)
    desired.x=T.MathUtils.clamp(desired.x,-9.7,9.7);desired.y=T.MathUtils.clamp(desired.y,.35,5.7);desired.z=T.MathUtils.clamp(desired.z,-7.7,7.7)
    camera.position.lerp(desired,1-Math.exp(-dt*5));camera.up.lerp(normal,1-Math.exp(-dt*4)).normalize();camera.lookAt(target)
  }
  renderer.render(scene,camera)
}
function resize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)}
window.addEventListener('resize',resize);resize();reset();updateBest()
let previous=performance.now();renderer.setAnimationLoop(now=>{const dt=Math.min((now-previous)/1000,.04);previous=now;animate(dt)})
